INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Divergence: Online', 'Divergence: Online is an open-world sandbox MMO that began as the spiritual successor to Pre-NGE SWG, but since has grown into its own living breathing universe. Divergence was designed to provide unmatched crafting, player and guild housing and player freedom on a scale, we believe, never before achieved. We hope you''ll enjoy our Early Access release and help us continue to develop this game!' FROM games WHERE igdb_id = 34007 ON CONFLICT (game_id, language_code) DO NOTHING;
