INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tour de France 2016', 'Embody the greatest cycling champions competing to conquer the yellow jersey along the 21 official stages of a Tour de France 2016, packed with exciting new features! Experience the emotions of a pro-rider by attacking, sprinting, counter-attacking; picking the best trajectories and taking the best tactical decisions to lead your team-mates to victory. Take to the road in solo, compete against your friends, or play in coop on the same screen.' FROM games WHERE igdb_id = 82417 ON CONFLICT (game_id, language_code) DO NOTHING;
