INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Network Superstar Soccer: Goal!!!', 'Become a soccer superstar with your favorite Cartoon Network characters in Superstar Soccer: Goal!!!, a crossover soccer mobile game. The game features Steven as a playable character alongside Garnet, Amethyst, Pearl, and various Cartoon Network characters from other shows. Unleash unique defensive dribbles and special moves for each character. Combine passing, shooting, dribbles and tackles to create your own awesome soccer plays and win the day. Play against the computer or challenge your soccer skills in multiplayer matches against other players. Enjoy versus play on the same device, over wiki or online.' FROM games WHERE igdb_id = 57738 ON CONFLICT (game_id, language_code) DO NOTHING;
