INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colonial Combat', 'Colonial Combat is the new, exciting, retro-styled, 1–vs–1, 2D, indie Unity3D fighting game for Windows 7 (and newer) PCs! The game is a fictional, comedic, non-violent fighting game with tongue-in-cheek satire and in-jokes about college life and surviving at a certain university, and based (loosely) on real campus settings as levels, and archetypal student types and figureheads as characters. The university’s mascot is Robert Morris (the financier of the American Revolution), and the football team is the “Colonial Crazies”, hence the title of the game.' FROM games WHERE igdb_id = 332651 ON CONFLICT (game_id, language_code) DO NOTHING;
