INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crows: Burning Edge', 'Crows: Burning Edge is an upcoming action-adventure game based on the Crows manga. The game will take place at the notorious Suzuran All-Boys High School, where Harumichi Boya is a recent transfer student. Harumichi is the kind of person who is devoted to fighting fairly, but it seems the other boys at the school aren’t as gracious. The game won’t only feature the thugs and delinquents from Suzaran High, however. Groups and gangs from Hosen Academy, the Kurotaki Alliance and the Front of Armament will showcase their fighting abilities as well.' FROM games WHERE igdb_id = 13521 ON CONFLICT (game_id, language_code) DO NOTHING;
