INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'She Who Fights Monsters: Choice Edition', 'Once upon a time, there was a sweet little girl with a big imagination. Her name was Jennifer (Jenny for short), and her world was full of adventure. A closet became a sanctuary. A basement became a secret passage to the Land of Elves. And her home became a nightmare world with no warning, rhyme or reason beyond the unpredictable winds of her father''s drunken rage.' FROM games WHERE igdb_id = 186168 ON CONFLICT (game_id, language_code) DO NOTHING;
