INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shitsuji ga Aruji wo Erabu Toki', 'All the visual novel elements are there featuring full voice-acting. On-screen text can be toggled off with ability to use analogue sticks to zoom and scroll the clear background image with characters. While this game is a port of an adult visual novel for Windows with the same title released a couple of years earlier, this version has all the adult content removed and main scenario adjusted to work accordingly.' FROM games WHERE igdb_id = 216245 ON CONFLICT (game_id, language_code) DO NOTHING;
