INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Rose and I', 'An immersive, animated VR film. Crafted by the artists, animators and storytellers of Penrose Studios, "The Rose And I" is about loneliness, friendship, love, and loss. Come meet a lonely Rose living in the unlikeliest of places, and join her as she transports you to a brand new universe.' FROM games WHERE igdb_id = 34596 ON CONFLICT (game_id, language_code) DO NOTHING;
