INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cladun Returns: This is Sengoku!', 'Cladun Returns: This is Sengoku! is the latest entry in the Cladun fantasy action RPG series. You as the player will meet classic heroes from Japan''s Sengoku Era and help the souls of the dead settle their unfinished business. Grant peace to these souls by traveling across feudal Japan and fighting your way through dungeons filled with monsters and traps!' FROM games WHERE igdb_id = 27331 ON CONFLICT (game_id, language_code) DO NOTHING;
