INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Escape: Midnight Carnival', 'You are Maya - a witch with magical powers investigating the mysterious Midnight Carnival on All Hallow’s Eye. You’ve barely arrived when you witness the kidnapping of Emily - a young girl in the wrong place at the wrong time. Her uncle Jack needs your help to save her. But almost immediately your investigation leads to danger. Could her kidnapping have been a trap to lure you deeper in the carnival?' FROM games WHERE igdb_id = 123442 ON CONFLICT (game_id, language_code) DO NOTHING;
