INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plants vs. Zombies: Garden Warfare 2', 'The battle for suburbia grows to crazy new heights in Plants vs. Zombies Garden Warfare 2! In this hilarious, action-packed shooter, zombie leader Dr. Zomboss has strengthened his horde and rebuilt suburbia as a zombie utopia. But hope remains, because for the first time the plants are taking the offensive in an all-out attack to reclaim their turf. Play as the plants in the all-new 24-player Herbal Assault mode, or choose your side in 4-player co-op or Solo Play!' FROM games WHERE igdb_id = 11148 ON CONFLICT (game_id, language_code) DO NOTHING;
