INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oz: Broken Kingdom', 'Battle the Great Darkness that has cast its shadow across the peaceful Land of Oz. Join the kingdom''s brave new heroine Ophelia Shen, along with the legendary heroes of Oz – Tin Man, Lion, and Scarecrow – as they embark on an epic quest to stop the rising evil, restore the balance of magic, and return the kingdom to its rightful glory.' FROM games WHERE igdb_id = 57861 ON CONFLICT (game_id, language_code) DO NOTHING;
