INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shantae-half-genie-hero', 11078, '2016-12-20', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ymj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4lyp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shantae: Half-Genie Hero', 'Shantae embarks on her first full HD adventure! After three highly successful outings with Shantae, Shantae: Risky''s Revenge, and Shantae and the Pirate''s Curse, Shantae and her friends finally get a full HD console-based sequel! Boasting vivid, detailed high-definition graphics that retain the 2D hand-drawn sprites the series is known for, this newest entry in the Shantae series almost looks like a playable TV show! Presented as a stage-based 2.5D platformer with heavy exploration elements, Shantae uses her trademark Hair-Whip Attack to dispatch enemies, then takes advantage of her Belly Dance Magic to transform into 8 different forms that each have their own unique abilities and move sets. As new forms are mastered, old stages can be re-explored to unearth new items and secrets, ensuring there''s plenty of content on offer for novices and platforming gurus alike. Topple the villainous Baron behind each criminal caper afflicting Sequin Land, and prepare for the ultimate showdown against Shantae''s arch-nemesis: that bodacious buccaneer, Risky Boots!' FROM games WHERE igdb_id = 11078 ON CONFLICT (game_id, language_code) DO NOTHING;
