INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DinoFense', 'Defend your Dino Village and Dinozens from being attacked by the uncivilized world! Play rescue missions on the Beach, in the Jungle, or near a Volcano by fighting off the angry cavemen and animals who imprisoned the dinosaurs. Defeat more enemies to unlock powerup items such as Dynamite to decimate your enemies, and keys to free your Dino friends. With adventure and endless modes, you can battle your way through each tier of difficulty or face wave after wave of enemies until you fail.' FROM games WHERE igdb_id = 30169 ON CONFLICT (game_id, language_code) DO NOTHING;
