INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatal Theory', 'Fatal Theory is nostalgic beat-em-up action with a fresh twist of ENDLESS AERIAL RAVE COMBOS and a killer illustrated story. Exercise your carnage muscle by smashing through huge hordes of unlovable fiends and take your crummy city back from the forces of hell!' FROM games WHERE igdb_id = 34681 ON CONFLICT (game_id, language_code) DO NOTHING;
