INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle Torgeath: Descent into Darkness', 'Castle Torgeath: Descent into Darkness is a unique blend of action, RPG, and survival in a 3D dungeon environment. Trapped in the dungeons of an ancient castle, you must scavenge for supplies, avoid traps, combat your foes, and confront the sinister threat that lurks within. As you try to find your way out of the dungeon, you will uncover the dark fate that befell its inhabitants.' FROM games WHERE igdb_id = 26590 ON CONFLICT (game_id, language_code) DO NOTHING;
