INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minecraft Education', 'Minecraft Education is a game-based learning platform that promotes creativity, collaboration and problem-solving in an immersive digital environment. Educators around the world use Minecraft: Education Edition to engage students across subjects and bring abstract concepts to life in remote, hybrid and in-person learning environments. With hundreds of standards-aligned lessons and STEM curricula, classroom-friendly features, tutorials and challenges, educators can access everything they need to get started with no experience required.' FROM games WHERE igdb_id = 28407 ON CONFLICT (game_id, language_code) DO NOTHING;
