INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Radiant Flux: Hyperfractal', 'Data-fractal hyper-structures are the new storage medium favoured by big companies. You are a neo-hacker, a new breed of bedroom fract-breaker, and these data structures are your playground. After receiving an unusual email instructing you to hack your own homepage, you discover a hidden world that will take you through the hack-zone and deep into the dark-web to yield untold riches in lost and forbidden software.' FROM games WHERE igdb_id = 85361 ON CONFLICT (game_id, language_code) DO NOTHING;
