INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abzu', 'Abzu is an exploration game where you are a lone diver in a lush ocean world. The diver descends deeper and deeper into the depths, where she will encounter majestic creatures, discover ancient secrets, and search for her true purpose. Abzu roughly translates to "The Ocean of Wisdom" from ancient Sumerian.' FROM games WHERE igdb_id = 7352 ON CONFLICT (game_id, language_code) DO NOTHING;
