INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Network: Battle Crashers', '"When Uncle Grandpa accidentally drives the UG-RV through multiple dimensions, he picks up some surprise passengers in the form of Gumball, Steven Universe, Finn, Mordecai and Clarence! Now they''ll have to band together to defeat the evil shard creatures and set things right. Use each character''s unique attacks and special moves to conquer the elements, fight your way through all the levels and beat some brutal boss battles. Replay maps with special modifiers to switch up the fun, and unlock bonus rooms along the way. Take on the single-player challenge in this crazy interdimensional adventure."
