INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slenderman Must Die: Chapter 6', 'In Slenderman Must Die: Industrial Waste, you''ll navigate terrifying and surreal industrial landscapes as you play a soldier lost in the chaos of war. Immerse yourself in the eerie silence as you work to find 9 vital notes that provide a way out. But beware of the lurking presence, Slenderman. This game combines elements of survival, horror, and first-person shooter gameplay for an unforgettable gaming experience.' FROM games WHERE igdb_id = 321072 ON CONFLICT (game_id, language_code) DO NOTHING;
