INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Card of Spirits', 'Card of Spirits is a card game in a Japanese cartoon style. The game has 8 ordinary cards with numbers through 1 - 8, and 4 special cards for a total of 12 cards. Every turn the player must surpass the total value of the opponent. The player with higher total value wins at the end of the game.' FROM games WHERE igdb_id = 32439 ON CONFLICT (game_id, language_code) DO NOTHING;
