INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3on3 FreeStyle', 'Welcome to one of the most vibrant, diverse, exciting and competitive but unifying sports in the world - street basketball. Pick your player from a pool of custom-designed, one-of-a-kind characters based on real-life street basketball players, team up with your friends online or in-person, and hit the court to play authentic, fast-paced 3 on 3 street basketball real-time matches against live opponents in settings inspired by the world’s most-revered street basketball venues. Once the ball is tipped, you can take on opponents with the signature, jaw-dropping basketball tricks each character possesses, link up with your teammates for soaring alley-oops and no-look passes, and create your own style which turns you into a street basketball legend.' FROM games WHERE igdb_id = 26405 ON CONFLICT (game_id, language_code) DO NOTHING;
