INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Utawarerumono: Mask of Truth', 'The epic story of Utawarerumono comes to an end in Mask of Truth, as the fate of the world will be determined by warring nations. The game features exciting SRPG battles, a colorful cast of new/familiar faces that will determine the fate of their world, a rousing original soundtrack, and the dramatic conclusion to the journey of Haku. After the events of Mask of Deception, Haku is destined to rally the nation of Ennakamuy to fight against the evil forces that now control the Yamato throne.' FROM games WHERE igdb_id = 26834 ON CONFLICT (game_id, language_code) DO NOTHING;
