INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Void', 'Drop into the retro-futuristic world of Marble Void! A 3D Platformer/Puzzler inspired by the 80''s. Pilot your Marble through puzzles and skill based obstacles to complete stages. With 3 tiers of difficulty and mini games, Marble Void is easy to pick up and play, yet tough to master! Moving platforms, switches, teleporters, gravity modifiers and more await you in 40+ stages of varying difficulties.' FROM games WHERE igdb_id = 33235 ON CONFLICT (game_id, language_code) DO NOTHING;
