INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku: Project Diva X', 'Hatsune Miku: Project Diva X is a rhythm game in the Project DIVA series of games featuring Crypton Future Media''s popular VOCALOID voicebanks. Sega confirmed the concept for the game is both live concerts, and producing. New to the series is the Live Quest story mode, which infuses the series'' classic rhythm gameplay with RPG elements.' FROM games WHERE igdb_id = 12078 ON CONFLICT (game_id, language_code) DO NOTHING;
