INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Time', 'The Last Time is an adventure game which combines retro graphics and game mechanics with modern nonlinear storytelling. You play as Jack Glover, a retired police officer who has withdrawn from society – until a mysterious phone call starts a series of events which forces him back into the real world. Now, he must face some new challenges: his physical frailty, his ignorance of modern technology, and his fear of connecting with people.' FROM games WHERE igdb_id = 23942 ON CONFLICT (game_id, language_code) DO NOTHING;
