INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love in the Glen', '“Love in the Glen” is a romantic otome visual novel/dating sim with a fun and charming match 3 minigame. Follow in the steps of Zoe Richardson, an interior designer living and working in Los Angeles’ exclusive and stylish Westside, as she explores the true meaning of love, commitment and passion and how it exists on so many different levels and planes.' FROM games WHERE igdb_id = 33083 ON CONFLICT (game_id, language_code) DO NOTHING;
