INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Brickout', 'Magical Brickout offers a new twist on the beloved classic Breakout formula. Instead of moving a small paddle back and forth across the screen you rotate the bricks in a circular fashion as you frantically try to keep the ball in the play area. This fast-paced and addictive gameplay is only half of the fun.' FROM games WHERE igdb_id = 25071 ON CONFLICT (game_id, language_code) DO NOTHING;
