INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tsundere Idol: My Personal M-Pet', 'Tsundere Idol is the story of Kota, a mild-mannered student in Japan and idol sensation Rui Kurumizaka. Too shy to approach the popular Rui, Kota is happy just to be in the same class at college. Then one day an accident occurs and the contents of Rui''s bag spill out on the floor revealing a naughty magazine! Our hero steps up to claim ownership and an unexpected and unusual affair begins.' FROM games WHERE igdb_id = 101246 ON CONFLICT (game_id, language_code) DO NOTHING;
