INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted 4: A Thief''s End', 'Several years after his last adventure, retired fortune hunter, Nathan Drake, is forced back into the world of thieves. With the stakes much more personal, Drake embarks on a globe-trotting journey in pursuit of a historical conspiracy behind a fabled pirate treasure. His greatest adventure will test his physical limits, his resolve, and ultimately what he''s willing to sacrifice to save the ones he loves.' FROM games WHERE igdb_id = 7331 ON CONFLICT (game_id, language_code) DO NOTHING;
