INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat Busters', 'When a brilliant cat scientist has one of her inventions stolen by mice, she sets out with adventurer friends to get it back. This action/RPG features a mix of RPG elements and pachinko. Players recruit adventurers and place them on the stage, where they can attack enemy units. At the bottom of the screen, players can flick to send a pachinko ball careening around the screen; bumping into the player''s units activates their special abilities, while bumping into enemies will damage them.' FROM games WHERE igdb_id = 56064 ON CONFLICT (game_id, language_code) DO NOTHING;
