INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Halcyon 6: Starbase Commander', 'Halcyon 6: Starbase Commander is a retro sci-fi strategy RPG with a unique blend of base building, exploration and deep tactical JRPG style combat system with capital starships and their idiosyncratic officers, all captured in stunningly beautiful modernized pixel graphics. In Halcyon 6, an unknown alien force is carving a path of destruction towards Earth and you, as the Commander of an immensely powerful, newly discovered derelict starbase left behind by a precursor alien race, are the best chance for the New Terran Federation to stop the impending invasion.' FROM games WHERE igdb_id = 18858 ON CONFLICT (game_id, language_code) DO NOTHING;
