INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alice''s Patchworks 2', 'Alice’s Patchwork 2 is a game of mosaic puzzles made of 6 different materials: wood, cloth, glass, paper, precious stones and metal. Assemble patchwork puzzles and guess the picture: a garden with talking flowers, a crazy tea party, cards come to life, the riddles of Humpty Dumpty, a duel between the Lion and the Unicorn, the intrigues of the Red Queen, a meeting with the White Rabbit… What other wonders await you in these 6 worlds? Put together all the mosaics and help Alice transform from a pawn into a queen!' FROM games WHERE igdb_id = 31438 ON CONFLICT (game_id, language_code) DO NOTHING;
