INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Secret of Middle City', 'Inspired by classics such as "Monkey Island" and "Broken Sword", intriguing and seducing like a "Twin Peaks" parody, "The Secret of Middle City" is an adventure that takes place in a typical north-american mountain town and that sees the protagonist, the goofy and clumsy Federal Agent Cox, strive among mysteries and false leads in order to solve a weird case of presumed homicide.' FROM games WHERE igdb_id = 31133 ON CONFLICT (game_id, language_code) DO NOTHING;
