INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero''s Song', '"Hero''s Song is an open world roguelike fantasy action RPG with a beautiful 2D pixel art style. Create epic fantasy worlds uniquely shaped by your choices, the power of the Gods, and thousands of years of procedurally generated history. Adventure alone or with up to 25 friends (during Early Access) on your own server and crush your foes. Become a legendary hero in a dangerous and mysterious world of magic and monsters. Explore endless dungeons and ancient cities in long-forgotten lands in search of knowledge, treasure, and the power of the Gods!"' FROM games WHERE igdb_id = 25870 ON CONFLICT (game_id, language_code) DO NOTHING;
