INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chesster', 'Chess meets match-three to create a deep and strategic new experience in Chesster, a indie chess puzzle simulator. Faced with a board full of chess pieces, you must create rows or columns of matching pieces to score points. Pieces move the same way as in chess and "take" the piece in their target destination, clearing it from the board.' FROM games WHERE igdb_id = 35674 ON CONFLICT (game_id, language_code) DO NOTHING;
