INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AcrossFlash', 'Across Flash is an arcade style shooter glider VR game developed by Uborm Technology Inc. You will guide one of two unique fighter crafts and explore a once great civilization that has fallen to ruin. Fly and battle through desolate arctic extremes, blustering desert ruins, scalding lava relic, or alien ecology.' FROM games WHERE igdb_id = 31446 ON CONFLICT (game_id, language_code) DO NOTHING;
