INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BOPZ.io', 'From the creators of ZOMBS ROYALE: Play the ultimate top-down 2D shooter, BOPZ.io! Engage in intense 5v5 battles, planting and defusing bombs while outsmarting your opponents. Your role impacts your team''s success, and their success shapes your experience. Prefer solo action? Go solo in various game modes that will test your skills. Jump into the fast-paced chaos and dominate the battlefield!' FROM games WHERE igdb_id = 304751 ON CONFLICT (game_id, language_code) DO NOTHING;
