INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bottom of the Well', 'In The Bottom of the Well, you play as Alice who has just had an unsettingly life-like dream about the end of the world. She retells her experience to her friend in a huge, branching narrative. Although a single play-through might take as little as 20 minutes, experiencing all the possible paths Alice can take through the ruins of her city will take you many hours.' FROM games WHERE igdb_id = 33370 ON CONFLICT (game_id, language_code) DO NOTHING;
