INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skynet Rising : Portal to the Past', 'Welcome to the world of Skynet Rising. From the mastermind creator Dr. Rex Havoc, Skynet Rising is a top notch action packed “Super Sandbox FPS”. Explore a beautifully crafted post apocalyptic world. Survive and conquer command towers through tough gun battles. Fight back to back with your brother in arms. Featuring a high adrenaline single player campaign, the game has a wickedly great Run and Gun gameplay with tons of "Shoot them in the face" fun.' FROM games WHERE igdb_id = 25738 ON CONFLICT (game_id, language_code) DO NOTHING;
