INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Witness', 'The Witness is a single-player game in an open world with dozens of locations to explore and over 500 puzzles. This game respects you as an intelligent player and it treats your time as precious. There''s no filler; each of those puzzles brings its own new idea into the mix. So, this is a game full of ideas.' FROM games WHERE igdb_id = 5601 ON CONFLICT (game_id, language_code) DO NOTHING;
