INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('this-is-the-police', 11423, '2016-07-27', 61, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1uu1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbwg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Is the Police', 'Jack Boyd, beloved police chief of Freeburg, has 180 days before he''s forced to retire. But Jack won''t be going out quietly. Over the next six months, he''ll be going all out to fulfill a dream: earn half a million dollars, any way he can. That might be play money for a corrupt cop, but up until now, Jack has been playing by the book. Even with overtime, in six months he wouldn''t make fifty grand. But a police chief has access to all sorts of… informal income. Bribes, weapons and drug sales, deals with the Mafia, skimming off the budget, kickbacks – you name it. And Jack is tired of playing nice. He''s is ready for anything, but only you can decide how far he''ll go.' FROM games WHERE igdb_id = 11423 ON CONFLICT (game_id, language_code) DO NOTHING;
