INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barony: Cursed Edition', 'Inspired by PC RPG classics of the past, such as Ultima Underworld, System Shock, Daggerfall, and Nethack, Barony: Cursed Edition places players in the shoes of a hero that must descend to the bottom of a dark dungeon known as the Devil''s Bastion and destroy an undead lich named Baron Herx, who terrorized the peaceful town of Hamlet in life and is now harboring a curse against the land from beyond the grave.' FROM games WHERE igdb_id = 51616 ON CONFLICT (game_id, language_code) DO NOTHING;
