INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scrap Garden', 'Scrap Garden is a charming puzzle platforming adventure where you play as the lonely robot Canny, who awakes in a post-apocalyptic world where all the other robotic citizens have been shut down and seized up. What happened to the City? Why did all the robots stop moving? Did anyone survive except him? Little rusty Canny has to do all he can to find the answers to these questions... and to fix everything!' FROM games WHERE igdb_id = 20340 ON CONFLICT (game_id, language_code) DO NOTHING;
