INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('defect', 21928, '2016-07-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3a9v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uhiwrxupbqvgbqjfqeh5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defect', 'In Defect, survive betrayal by your own creation - your own ship will be coming back to destroy you, your only hope is to build something better - this time, and every time. In Defect, mutiny is inevitable. Survive against your own creations by building the ultimate spaceship, dogfighting to get through every betrayal. With over 1 billion customisation options, this tale of space mutiny creates the experience of building your own boss - as every ship will be torn from you and become your next boss to defeat. Every spaceship creation builds a unique theme soundtrack, with an epic scale of dogfighting as a single-pilot fighter, all the way to a space station the size of a small moon. Cross-platform play and an unprecedented freedom of spaceship battle creation awaits you.' FROM games WHERE igdb_id = 21928 ON CONFLICT (game_id, language_code) DO NOTHING;
