INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sombrero: Spaghetti Western Mayhem', 'To all you desperadoes, drifters, and cowboys, SOMBRERO is calling you out for a rapid-fire game of spaghetti western mayhem for 2-4 players. Choose a character, load up your six-shooters, and lunge through a non-stop hailstorm of bullets and TNT as you race to grab loot and blast your friends with authentic weaponry and …they had exploding rocket-powered fists back then, right?' FROM games WHERE igdb_id = 20758 ON CONFLICT (game_id, language_code) DO NOTHING;
