INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ember', 'A passion project 10 years in the making, Ember is a homage to classic role-playing games (RPG). Enter the world of Ember as a resurrected “Lightbringer” summoned to protect the dying Embers as the world is on the brink of collapse. Beginning in the Deep Barrows, traverse vast environments divided between aboveground and underground realms – ranging from lush forests to dry deserts and dark abysses – to reach the City of Light. See how the story unfolds through encounters with strangers by making pivotal decisions about your own destiny.' FROM games WHERE igdb_id = 23941 ON CONFLICT (game_id, language_code) DO NOTHING;
