INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Metronomicon: Slay the Dance Floor', 'Packing in a fully-fledged story mode with a colourful cast of musically-empowered heroes and villains, The Metronomicon sees you take control a party of eight newly graduated masters of the "rhythmic combat arts" to wage musical warfare against a multitude of dance-mongering fiends. By switching between four concurrent hero-controlled tracks on-the-fly, you''ll select and activate a wide array of abilities and spells, buffs and nukes, with your performance and timing all-important in ensuring the effectiveness of your moves.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 19880 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
