INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic.EXE: The Assault', 'Forgetfulness… Regret… Revenge… When he makes mistakes… what would a father get from his son? What would a son do to calm his sorrow? And what would a ruthless demon commit to feed his rage.. And to calm his hunger? Play the game and resolve the mysteries through a bunch of spooky environments, lots of obstacles, challenging puzzles & an intense terrifying gameplay!' FROM games WHERE igdb_id = 321068 ON CONFLICT (game_id, language_code) DO NOTHING;
