INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Phantom Cat: Super Nyan Edition', 'Super Phantom Cat: Super Nyan Edition is a standalone expansion of the retro-style platformer Super Phantom Cat. Players jump, dash, and activate spirit powers to explore pixel-rich levels filled with whimsical dangers. This edition introduces themed characters such as Vampire Cat and Android Cat, each with unique abilities and visual effects, along with Nyan-inspired skins, day/night stage variations, and customizable controls. Gameplay emphasizes precision platforming and light puzzle-solving within a charming 2D world.' FROM games WHERE igdb_id = 220933 ON CONFLICT (game_id, language_code) DO NOTHING;
