INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Calcu-Late', 'Calcu-Late is a story about a boy named James that needs to participate in a godly Olympics tournament as a representative for the goddess of mathematics, Seshat. The tournament will grant the participant a wish that they stated before the tournament starts. James is going to take a final math exam in his school, but he forgot to study for it. His wish is just to pass the math exam.' FROM games WHERE igdb_id = 33331 ON CONFLICT (game_id, language_code) DO NOTHING;
