INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Hunter Stories', 'Monster Hunter Stories is a role-playing game spin-off of the popular Monster Hunter franchise, but features a drastically different gameplay focus. Unlike previous titles in the franchise, Monster Hunter Stories lets players take on the role of a Rider instead of a Hunter, and are able to take part in a traditional turn-based battle system. Major changes and additions featured in this title include hatching eggs and befriending monsters, battling alongside them, executing special kinship techniques, and customizing monsters'' abilities and appearance' FROM games WHERE igdb_id = 9692 ON CONFLICT (game_id, language_code) DO NOTHING;
