INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DreamLand', '“DreamLand” is an immersive VR game, made by AAA team base on htcVIVE with Unreal Engine. With the VR device, the player could pass through the Portal of Astral Spirit, and explore the mystical dreamland by time travel. In this journey, the player can identify the secret of the ancient civilization via solving puzzles, which make the player immerse in a fantastical experience of audio and visual.' FROM games WHERE igdb_id = 32173 ON CONFLICT (game_id, language_code) DO NOTHING;
