INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bunker', 'The Bunker is a completely live action experience with point-and-click interactivity. Filmed on location in a decommissioned government nuclear bunker, it features a plot crafted by writers and designers behind titles like The Witcher, SOMA and Broken Sword, and incredible cast including Adam Brown (The Hobbit) and Sarah Greene (Penny Dreadful, Assassin’s Creed 3).' FROM games WHERE igdb_id = 24017 ON CONFLICT (game_id, language_code) DO NOTHING;
