INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Three Bosses', 'Good old fashioned jump adventure. Jump, run, fight! Join the adventure and fight against ultimate enemies. Collect coins to unlock 9 unique blocky warriors. Ability to double jump brings up classic old school fun. Invisibility, mega size, shrinking, shielding...Get secret power-up props along the adventure to join the final battle with the 3 Bosses.' FROM games WHERE igdb_id = 174323 ON CONFLICT (game_id, language_code) DO NOTHING;
