INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hacker Evolution Immersion', 'Mankind had its fastest technological progress in recent history. Uncover a dark secret that goes back to the days of the first Russian space project. Use your hacker skills to start uncovering a dark secret, by going through the past from the early days of computers, all the way to the most advanced computers of the future.' FROM games WHERE igdb_id = 25842 ON CONFLICT (game_id, language_code) DO NOTHING;
