INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asher', 'A retro inspired, platforming RPG. Set in a young boys world of dreams and nightmares. Level up, collect masks, unlock unique abilities, choose stats, and take on challenging bosses. Using fast action, skill shots, and responsive player controls, Asher allows for a challenging and enjoyable game play experience. While playing as Asher it is up to you to take on the things haunting your dreams, find your sister Lila, and bring her back home.' FROM games WHERE igdb_id = 33483 ON CONFLICT (game_id, language_code) DO NOTHING;
