INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clockwork Empires', 'Take on the role of a Junior Bureaucrat (Colonial Grade), sent forth to seek fame, promotions, and natural resources to feed the ravenous maw of Imperial Industry & Commerce. Build a prosperous colony, fill it with magnificent factories worked by oppressed labourers, and harness the awesome power of steam through fearsome machines invented by determined men and women of Science! History is yours to seize for fame and fortune, for Science, and for the Queen and the glory of the Clockwork Empires!' FROM games WHERE igdb_id = 9764 ON CONFLICT (game_id, language_code) DO NOTHING;
