INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vistascapes VR', 'Have you ever wished to be sitting next to a fireplace during a rainstorm, camping in the woods, or standing on the edge of a beautiful mountainous landscape? Now you can with this virtual reality (VR) room-scale experience. Available for the HTC Vive, this experience will be more relaxing and exciting than anything available for the price. This game isn''t quite classified as a game, but thats the point! It''s more of an experience.' FROM games WHERE igdb_id = 32891 ON CONFLICT (game_id, language_code) DO NOTHING;
