INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('inversus', 19608, '2016-08-16', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qfr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arnbq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inversus', '"Inversus is a minimalist action-strategy shooter for one to four friends. It''s reminiscent of the board game Othello, except it''s running in real time and everyone has guns. Player movement is constrained to opposite colors of a black and white grid. My walls are your paths and your walls are my paths. Each shot flips tile colors in an attempt to block, trap and close in on the enemy. Both online and local couch play are supported. The competitive versus mode pits players against each other in 1v1 or 2v2 battles. There are also single-player and two-player cooperative modes that mix the negative-space combat with a classic score-driven arcade game."' FROM games WHERE igdb_id = 19608 ON CONFLICT (game_id, language_code) DO NOTHING;
