INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Warrior 2', '"Shadow Warrior 2 is the stunning evolution of Flying Wild Hog’s offbeat first-person shooter following the further misadventures of former corporate shogun Lo Wang. Now surviving as a reclusive mercenary on the edge of a corrupted world, the formidable warrior must again wield a devastating combination of guns, blades, magic and wit to strike down the demonic legions overwhelming the world. Battle alongside allies online in four-player co-op or go it alone in spectacular procedurally-generated landscapes to complete daring missions and collect powerful new weapons, armor, and arcane relics of legend."' FROM games WHERE igdb_id = 11064 ON CONFLICT (game_id, language_code) DO NOTHING;
