INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Malavision: The Origin', 'A politician runs away upon sued corruption acts against him were proved. He gets in a private property located in the Paraguayan Chaco. As his assistant disappears, he decides to go into his quest. What is awaiting him to live has existed only in the imagination, myth and superstition. He must overcome any kind of obstacles as a way to survive in a hostile environment, disturbed in time and space.' FROM games WHERE igdb_id = 31812 ON CONFLICT (game_id, language_code) DO NOTHING;
