INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kalaban', 'Kalaban is a horror-themed 2D action-adventure. The game focuses on story-telling and open-ended gameplay. The game is set in the year 1995, in an alternate history version of Finland. The main character of the game is Bob, a hermit and an American who has moved to Finland. Bob''s cabin is attacked by a mutant monster, which triggers the story. He must find out what is going on around him and discover the reason behind the weird outbreak.' FROM games WHERE igdb_id = 30094 ON CONFLICT (game_id, language_code) DO NOTHING;
