INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Take Off: The Flight Simulator', 'Fly more than 20 airplanes in an open world or try out more than 40 excitng and varied missions – from airfreighting to dramatic rescue operations! You can also establish your own airline and fly to cities such as New York, London, Sydney and 18 other destinations. Fly the most popular models of planes, such as jumbo jets, seaplanes and a military jet with realistically designed 3D cockpits. Experience challenging weather conditions and try to land your plane safely with an engine failure!' FROM games WHERE igdb_id = 89683 ON CONFLICT (game_id, language_code) DO NOTHING;
