INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Rats Show', 'Bad Rats Show is a physics puzzle game where the rats exact their bloody revenge against their main enemies: the Cats. Solve puzzles in 2D and 3D maps using physics, objects and specially trained Rats. All new Rats and Cats, but with the same classic and questionable Bad Rats humor. With the new map editor you can download, create and share new levels. With unlimited solutions for each puzzle, flex your creativity and enjoy the show!' FROM games WHERE igdb_id = 27510 ON CONFLICT (game_id, language_code) DO NOTHING;
