INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Z-Exemplar', 'Z-Exemplar is a side-scrolling shooter in the tradition of R-Type, Gradius, Nemesis and other classic arcade games from the past. Borrowing its aesthetic from the computers of yesteryear (specifically the Sinclair ZX Spectrum) Z-Exemplar combines bright, bold, 8-bit pixel art with frantic action and an epic mission to conquer a galaxy of almost 1000 planets.' FROM games WHERE igdb_id = 26010 ON CONFLICT (game_id, language_code) DO NOTHING;
