INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hangul Attack', 'Hangul Attack is a typing game where the objective is to destroy the Hangul characters that fall from the sky. Four modes help the user focus on consonants, vowels, consonants and vowels, and words. There is also a master mode that does not have a time limit, allowing the user to see how many points they can earn.' FROM games WHERE igdb_id = 141664 ON CONFLICT (game_id, language_code) DO NOTHING;
