INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Collar x Malice', 'Collar x Malice is a visual novel, and follows Ichika Hoshino, who is patrolling Shinjuku, Tokyo. She is attacked, and a collar with poison is placed around her neck; following this, she becomes involved with the "X-Day Incident", which is being investigated by five former police officers.' FROM games WHERE igdb_id = 12634 ON CONFLICT (game_id, language_code) DO NOTHING;
