INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viking Squad', 'Grab your trusty sword, strap on a fearsome helmet, and plunge into the chaotic fray of Viking Squad! As a member of this ragtag group you must put a stop to the wildly mischievous Loki and reopen the gates to Valhalla. Work together to unleash massive attacks on foes and expand your arsenal in this three player co-op brawler.' FROM games WHERE igdb_id = 24837 ON CONFLICT (game_id, language_code) DO NOTHING;
