INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 0', 'Be prepared to relive the first nightmare in Resident Evil 0, a remastered version of the popular prequel to the original Resident Evil game. This remastered version takes the fear-inducing atmosphere from the original 2002 release and transforms it with stunning new HD visuals, improved sound, widescreen support and an optional modernized control system and more. It''s the best way to experience the story of what really happened before the iconic mansion incident that was the catalyst for the entire Resident Evil saga.' FROM games WHERE igdb_id = 15108 ON CONFLICT (game_id, language_code) DO NOTHING;
