INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gardenscapes', 'Gardenscapes is a casual puzzle game developed by Playrix where players embark on a journey to restore and beautify a neglected garden. The protagonist, Austin the butler, inherits a sprawling but dilapidated garden and mansion and enlists the player''s help to renovate it to its former glory. The gameplay primarily revolves around completing match-3 puzzle levels to earn stars, which are then used to progress in the garden renovation process and unlock new areas to restore.' FROM games WHERE igdb_id = 63434 ON CONFLICT (game_id, language_code) DO NOTHING;
