INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Master of Orion', 'Master of Orion, the award-winning and critically acclaimed strategy game, has returned. The iconic 4X strategy gameplay of Explore, Expand, Exploit and Exterminate that formed the blueprint for a whole generation has been resurrected and upgraded. Stunningly enhanced for a new line of players, Master of Orion inherits and redefines its core elements, providing a graphically beautiful and deeply rewarding experience.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 11507 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
