INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Turing Test', 'The Turing Test is a first person puzzler that explores the phenomena of consciousness and challenges the meaning of human intuition. Take control of Ava Turing, an engineer for the International Space Agency (ISA), and progress through a narrated story of introspection and morality whilst uncovering the hidden mysteries of Europa.' FROM games WHERE igdb_id = 18311 ON CONFLICT (game_id, language_code) DO NOTHING;
