INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agricola: All Creatures Big and Small', 'In Agricola: All Creatures Big & Small, the player is the owner of an old farmstead with a bit of land. However, a neighboring farmer happens to have a competitive streak — so all bets are off! Both players (human and CPU) must use their wits to acquire and manage both resources and livestock over eight rounds — while attempting to strategically deploy buildings — in a mad dash for farm and fortune.' FROM games WHERE igdb_id = 24025 ON CONFLICT (game_id, language_code) DO NOTHING;
