INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duckie Dash', 'Duckie Dash is a casual racing game that can be played solo or with up to 4 players split-screen. Race rubber duckies across 30 different levels with features like jet streams, geysers, and more! Easy enough for small children to play, but timed challenges make it fun for adults too! The whole family will enjoy Duckie Dash!' FROM games WHERE igdb_id = 32811 ON CONFLICT (game_id, language_code) DO NOTHING;
