INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Hole Hazard', 'Black Hole Hazard is an action puzzle spacewalking game with unique control and a fascinating sci-fi story. Controlling the gun''s recoil in space and distorted gravity will be very challenging. Be Dr. Albert, shoot the jet / laser gun to survive against the unknown enemies and find out the truth.' FROM games WHERE igdb_id = 32515 ON CONFLICT (game_id, language_code) DO NOTHING;
