INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Through the Woods', 'Through the Woods is a third-person psychological horror game set in a forest on the western shore of Norway about a mother and her missing son. Through dynamic narration, you play the mother''s re-telling of the events surrounding her son''s disappearance in a setting heavily influenced by Norse mythology and Norwegian folk tales.' FROM games WHERE igdb_id = 9525 ON CONFLICT (game_id, language_code) DO NOTHING;
