INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('duke-grabowski-mighty-swashbuckler', 23982, '2016-10-06', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1smk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4r8u.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duke Grabowski: Mighty Swashbuckler', 'Duke Grabowski: Mighty Swashbuckler is a classic point-and-click adventure, created with love by an indie team that includes LucasArts alumni, Bill Tiller (The Curse of Monkey Island, Steven Spielberg''s The Dig, Indiana Jones and the Infernal Machine). Play as Duke, a pirate who’s had success in pillaging, ransacking, and other forms of piratey goodness, but doesn’t know a thing about women. Help him prove to his crew he has what it takes to become a captain by winning the affection of the opposite sex – a task that is the most difficult challenge this seasoned pirate has faced! Along his journey to “sea-deuce” he’ll have to tame jaguars, fight zombie sailors, and even wrestle a gorilla!' FROM games WHERE igdb_id = 23982 ON CONFLICT (game_id, language_code) DO NOTHING;
