INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom', 'Developed by id software, the studio that pioneered the first-person shooter genre and created multiplayer Deathmatch, Doom returns as a brutally fun and challenging modern-day shooter experience. Relentless demons, impossibly destructive guns, and fast, fluid movement provide the foundation for intense, first-person combat – whether you’re obliterating demon hordes through the depths of Hell in the single-player campaign, or competing against your friends in numerous multiplayer modes. Expand your gameplay experience using Doom SnapMap game editor to easily create, play, and share your content with the world.' FROM games WHERE igdb_id = 7351 ON CONFLICT (game_id, language_code) DO NOTHING;
