INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynamite Alex', 'Dynamite Alex is an action platform-shooter starring a 17-year old tomboy named Alexandra Tobynskii. After a rather cliched outbreak of robbers invading the city, it''s up to her to investigate what''s going on! Sans loading screens, and donning glorious retro colors and mechanics, Dynamite Alex transports players back to a time where gameplay was king!' FROM games WHERE igdb_id = 31343 ON CONFLICT (game_id, language_code) DO NOTHING;
