INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AffordaGolf Online', 'AffordaGolf is a Multiplayer Online Mini-golf game!In AffordaGolf you can play mini-golf with your friends and up to 127 people on unlimited amount of maps (courses).Key FeaturesOnline Multiplayer up to 127 players in same map.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 30138 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
